// test6.mjs
// Node.js (ESM) port of /workspace/dataset/bencoder/test6.py
// Original:
//   list_data = [args.a.encode('ascii'), args.b, [args.b]]
//   encoded = bencoder.encode(list_data)
//   decoded = bencoder.decode(encoded)
//   print(encoded)
//   print(decoded)

import { basename } from 'node:path';
import { ArgumentParser } from './lib/argparse.mjs';
import { PyBytes, UnicodeEncodeError } from './lib/pybytes.mjs';
import { pyRepr } from './lib/pyrepr.mjs';
import { encode, decode } from './lib/bencoder.mjs';

const parser = new ArgumentParser(basename(process.argv[1]));
parser.addArgument('--a', { type: 'str', required: true });
parser.addArgument('--b', { type: 'int', required: true });
const args = parser.parseArgs(process.argv.slice(2));

let aBytes;
try {
  aBytes = PyBytes.fromAscii(args.a); // args.a.encode('ascii')
} catch (e) {
  if (e instanceof UnicodeEncodeError) {
    process.stderr.write('Traceback (most recent call last):\n');
    process.stderr.write('  File "test6.py", line 9, in <module>\n');
    process.stderr.write(`UnicodeEncodeError: ${e.message}\n`);
    process.exit(1);
  }
  throw e;
}

const listData = [aBytes, args.b, [args.b]];
const encoded = encode(listData); // Encode nested list
const decoded = decode(encoded); // Decode the encoded data
console.log(pyRepr(encoded));
console.log(pyRepr(decoded));

